import { useState } from 'react';
import type { FormEvent } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { setAsOf, useAsOf } from '../../api/asOf';
import { SheetPanel } from '../../slots/defs/sheetPanel';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Whether the text is a real date (yyyy-mm-dd). */
function isDate(text: string): boolean {
  if (!DATE.test(text)) return false;
  const d = new Date(`${text}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === text;
}

/**
 * Shows the sheet as of a date, on this user's screen only: every figure, flag, list and line as it stood at the
 * end of that date, the date standing in for the sheet's today. While it is set every change is refused (by the
 * server, with the usual error of the form or action). Clearing it shows the sheet as it is now.
 */
function AsOfView() {
  const asOf = useAsOf();
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState('');
  const [error, setError] = useState('');

  // Every query kept per sheet is read afresh for the new date; none shows what it read for another.
  const show = (date: string) => {
    setAsOf(date);
    void queryClient.resetQueries({ queryKey: ['sheet'] });
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const date = typed.trim();
    if (!isDate(date)) {
      setError('The as-of date must be a date (yyyy-mm-dd).');
      return;
    }
    setError('');
    show(date);
  };

  return (
    <form data-testid="asof-form" onSubmit={submit}>
      As of <strong data-testid="sheet-asof">{asOf}</strong>{' '}
      <input
        data-testid="asof-date"
        placeholder="yyyy-mm-dd"
        value={typed}
        onChange={(e) => {
          setTyped(e.target.value);
          setError('');
        }}
      />{' '}
      <button type="submit" data-testid="asof-set">
        Show as of
      </button>{' '}
      <button
        type="button"
        data-testid="asof-clear"
        onClick={() => {
          setError('');
          setTyped('');
          show('');
        }}
      >
        Show now
      </button>
      {error && <p data-testid="asof-error">{error}</p>}
    </form>
  );
}

export const contribution = SheetPanel.fill({ order: 0.5, Component: AsOfView });
import { useSyncExternalStore } from 'react';

// The date this user's screen is shown as of (yyyy-mm-dd), '' when it shows the sheet as it is now. It
// belongs to this screen only: every request names it (X-As-Of, see http.ts), so the server answers a read
// as the store stood at the end of that date and refuses every change while it is set.
let asOf = '';
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** The as-of date the requests name now ('' for none). */
export function currentAsOf(): string {
  return asOf;
}

export function setAsOf(date: string): void {
  if (asOf === date) return;
  asOf = date;
  listeners.forEach((l) => l());
}

/** The as-of date shown on this screen ('' for none). */
export function useAsOf(): string {
  return useSyncExternalStore(subscribe, () => asOf);
}
import { currentAsOf } from './asOf';

// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A write refused because the record was saved by someone else since it was loaded (409). */
export class ConflictError extends Error {}

/** A write refused by a rule the screen cannot see in full (422), e.g. a claim dated in a closed period; the message is the server's. */
export class RefusedError extends Error {}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // A screen shown as of a date names it on every request: reads come back as of it, changes are refused (422).
  const asOf = currentAsOf();
  const res = await fetch(path, asOf ? { ...init, headers: { ...init?.headers, 'X-As-Of': asOf } } : init);
  if (res.status === 409) {
    throw new ConflictError(`${init?.method ?? 'GET'} ${path} -> 409`);
  }
  if (res.status === 422) {
    throw new RefusedError(await res.text());
  }
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

/** A read; with a user, it names the signed-in user (X-User) for a read whose answer depends on who asks. */
export function getJson<T>(path: string, user?: string): Promise<T> {
  return send<T>(path, user ? { headers: { 'X-User': user } } : undefined);
}

// A write names the signed-in user (X-User) so the server can record who made the change.
function jsonHeaders(user?: string): HeadersInit {
  return user ? { 'Content-Type': 'application/json', 'X-User': user } : { 'Content-Type': 'application/json' };
}

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}
