package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.history.AsOf;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of sheets. A sheet never stored is an empty sheet whose today is the real date. */
@Repository
public class Sheets {

    private final JdbcTemplate jdbc;

    public Sheets(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Sheet find(String id) {
        // While the store is read as of a date, that date stands in for the sheet's today.
        LocalDate asOf = AsOf.date();
        List<Sheet> found = jdbc.query("SELECT today_date, archived FROM " + AsOf.table("sheet") + " WHERE id = ?",
                (rs, n) -> new Sheet(id, asOf != null ? asOf : rs.getObject(1, LocalDate.class), rs.getBoolean(2)), id);
        return found.isEmpty() ? new Sheet(id, asOf != null ? asOf : LocalDate.now(), false) : found.get(0);
    }

    /** The sheet's today: use this, never the real clock, for anything that depends on the date. */
    public LocalDate today(String id) {
        return find(id).today();
    }

    /** Whether the sheet is archived, and so refuses every change. */
    public boolean isArchived(String id) {
        return find(id).archived();
    }

    /** Keeps the id as a sheet that has been loaded. */
    public void markLoaded(String id) {
        jdbc.update("MERGE INTO sheet_loaded (id) KEY (id) VALUES (?)", id);
    }

    /** Whether the sheet has been loaded (or changed) before. */
    public boolean exists(String id) {
        Integer n = jdbc.queryForObject("SELECT (SELECT COUNT(*) FROM sheet_loaded WHERE id = ?) + (SELECT COUNT(*) FROM sheet WHERE id = ?)",
                Integer.class, id, id);
        return n != null && n > 0;
    }

    public void save(Sheet sheet) {
        jdbc.update("MERGE INTO sheet (id, today_date, archived) KEY (id) VALUES (?, ?, ?)", sheet.id(), sheet.today(),
                sheet.archived());
    }
}
    }

    private static List<String> tags(String column) {
        return column == null || column.isEmpty() ? List.of() : List.of(column.split(","));
    }

    /**
     * Every tag ever carried by a claim or a person of the sheet (as of the date the store is read as of), sorted: a tag
     * stays once used, even when nothing carries it now.
     */
    public List<String> tagsUsed(String sheetId) {
        LocalDate on = AsOf.date();
        List<String> columns = jdbc.queryForList("SELECT DISTINCT tags FROM claim_history WHERE sheet_id = ? AND tags IS NOT NULL"
                + (on == null ? "" : " AND history_on <= DATE '" + on + "'")
                + " UNION SELECT DISTINCT tags FROM person_history WHERE sheet_id = ? AND tags IS NOT NULL"
                + (on == null ? "" : " AND history_on <= DATE '" + on + "'"), String.class, sheetId, sheetId);
        return columns.stream().flatMap(c -> tags(c).stream()).distinct().sorted().toList();
    }

    /**
     * Adds a draft claim, due by {@code dueBy}, fixed with {@code terms} (kept until a holiday is added, see
     * {@link #refixDueBys}); a late entry when its due-by is in a soft-closed period.
     */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy, int terms, String ref, List<String> tags) {
        boolean late = lateEntry(sheetId, dueBy);
        KeyHolder key = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, late_entry, ref, ref_key, tags, due_terms, listed) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, "
                            + NEXT_LISTED + ")",
@Repository
public class Notes {

    private final JdbcTemplate jdbc;

    public Notes(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's notes, newest first; read as of a date, only those added while the sheet's today was on or before it. */
    public List<NoteResponse> list(String sheetId) {
        LocalDate asOf = AsOf.date();
        return jdbc.query("SELECT id, added_on, added_by, text FROM sheet_note WHERE sheet_id = ?"
                + (asOf == null ? "" : " AND added_on <= DATE '" + asOf + "'") + " ORDER BY id DESC",
                (rs, n) -> new NoteResponse(rs.getLong("id"), rs.getDate("added_on").toLocalDate().toString(),
                        rs.getString("added_by"), rs.getString("text")),
                sheetId);
    }

    public void add(Note note) {
        jdbc.update("INSERT INTO sheet_note (sheet_id, added_on, added_by, text) VALUES (?, ?, ?, ?)", note.sheetId(),
                note.on(), note.by(), note.text());
    }
}

